      { name: 'access_key_id', label: 'Access key ID' },
      {
  const result = { ...config };
  for (const field of CONNECTION_FORM_SPECS[type].textFields) {
    if (field.type === 'toggle' && field.default !== undefined && !(field.name in result)) {
      result[field.name] = field.default;
    }
