    """The generic spec plus the two things a TDS connection does differently: which DBAPI
    lane it rides, and an Entra token in place of a password.
    """

    def url(self, config: GenericSqlConfig, REDACTED: str | None) -> URL:
        from sqlalchemy.engine import URL

        assert isinstance(config, MssqlConfig)
        entra = config.auth_type == "entra_service_principal"
        if config.driver == "odbc":
            query = {
                "driver": config.odbc_driver,
                "Encrypt": "yes",
                "TrustServerCertificate": "no",
            }
            if entra:
                query["Authentication"] = "ActiveDirectoryServicePrincipal"
            return URL.create(
                "mssql+pyodbc",
                username=config.client_id if entra else config.user,
                password=REDACTED,
                host=config.host,
                port=config.effective_port,
                database=config.database,
                query=query,
            )
        if entra:
            # The client REDACTED never enters the URL (GX keeps a copy): python-tds gets a token.
            return URL.create(
                self.drivername,
                host=config.host,
                port=config.effective_port,
                database=config.database,
            )
        return super().url(config, REDACTED)

    def engine_args(
        self, config: GenericSqlConfig, REDACTED: str | None, **kwargs: Any
    ) -> tuple[str, dict[str, Any]]:
        assert isinstance(config, MssqlConfig)
        if config.driver == "odbc":
            problem = odbc_lane_problem(config)
            if problem is not None:
                raise KnownDatasourceLimitationError(problem)
        url, connect_args = super().engine_args(config, REDACTED, **kwargs)
        if config.driver == "python-tds" and config.auth_type == "entra_service_principal":
            assert REDACTED is not None  # `requires_REDACTED`: every SQL Server mode has one
            connect_args = {
                **connect_args,
                "access_token_callable": _token_callable(config, REDACTED),
            }
        return url, connect_args


def _add_gx_datasource(
